--
-- Table structure for table `lottery_odds_categories`
--

DROP TABLE IF EXISTS `lottery_odds_categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lottery_odds_categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL DEFAULT '1',
  `lottery_id` bigint unsigned NOT NULL,
  `name` varchar(80) NOT NULL,
  `is_playable` tinyint(1) DEFAULT '0',
  `min_bet` decimal(12,4) DEFAULT NULL,
  `odds_limit` decimal(12,4) DEFAULT NULL,
  `single_bet_limit` decimal(14,2) DEFAULT NULL,
  `single_item_limit` decimal(14,2) DEFAULT NULL,
  `odds` decimal(12,4) DEFAULT NULL,
  `offline_rebate` decimal(10,4) DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `sort` int NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_odds_category` (`lottery_id`,`name`),
  KEY `idx_odds_category_tree` (`lottery_id`,`status`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

